function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function writeStore(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{}}
let lang=readStore('enu-lang','kk'); if(!translations[lang])lang='kk';
let page='assistant',documents=[],history=readStore('enu-history',[]),saved=readStore('enu-saved',[]),current=null,busy=false,loadError=false,filter='all',staff=false,searchTerm='',lastFocus=null,chatReady=false,conversationMode='documents',modelSettings={provider:'local',model:'qwen2.5:3b',key_saved:false,allow_documents:false},modelCache={};
const t=key=>translations[lang][key]||key;
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.file}"/></svg>`;
const $=s=>document.querySelector(s);
function node(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;}
function button(text,action,cls=''){const e=node('button',cls,text);e.type='button';e.addEventListener('click',action);return e;}
function toast(text){const e=$('#toast');e.textContent=text;e.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('visible'),3500);}
async function api(path,body){const response=await fetch(path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});let data;try{data=await response.json();}catch{throw Error(t('error'));}if(!response.ok)throw Error(data.code?providerError(data.code):(data.error||t('error')));return data;}
function navigate(target){page=target;render();window.scrollTo(0,0);}
function newQuestion(){if(busy)return;current=null;navigate('assistant');$('#question')?.focus();}
function navItem(target,label,glyph){return `<button type="button" data-nav="${target}" class="${page===target?'active':''}">${icon(glyph)}<span>${t(label)}</span>${target==='library'?`<span class="badge">${documents.length}</span>`:''}</button>`;}
function render(){
 document.documentElement.lang=lang;$('.skip').textContent=t('skip');document.title=`ENU Көмек · ${t(page==='library'?'library':page==='saved'?'saved':'assistant')}`;
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="/favicon.svg" alt=""><div><strong>ENU Көмек</strong><small>${t('subtitle')}</small></div></div><button type="button" class="new" id="new">${icon('plus')}${t('new')}</button><nav class="nav" aria-label="${t('navigation')}">${navItem('assistant','assistant','chat')}${navItem('library','library','book')}${navItem('saved','saved','bookmark')}</nav><div class="side-label">${t('recent')}</div><div class="history" id="history"></div><div class="side-bottom"><div class="local-status"><span class="dot"></span>${t(modelSettings.provider!=='local'?'cloudStatus':'localStatus')}<small>${(modelSettings.provider!=='local'?cloudPrivacy(modelSettings.provider):t('localSub'))}</small></div><button type="button" class="sidebar-settings" id="settings">${icon('sparkle')}<span>${t('settings')}</span>${icon('chevron')}</button><div class="profile"><div class="avatar">EN</div><div>${t('profile')}<small>${t('workspace')}</small></div></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">ENU Көмек ${icon('chevron')}<b>${t('breadcrumb')}</b></div><div class="mobile-brand"><img src="/favicon.svg" alt="">ENU Көмек</div><div class="top-actions"><button type="button" class="model-switch" id="model-settings" aria-label="${t('settings')}"><span class="model-symbol">${modelSettings.provider!=='local'?'✦':'◈'}</span><span class="model-switch-text"><small>${providerTitle(modelSettings.provider).toUpperCase()}</small><b id="active-model-name"></b></span>${icon('chevron')}</button><div class="language" aria-label="${t('languageLabel')}"><button type="button" data-lang="kk" class="${lang==='kk'?'selected':''}">ҚАЗ</button><button type="button" data-lang="ru" class="${lang==='ru'?'selected':''}">РУС</button></div><button class="icon-button" id="help" aria-label="${t('about')}">${icon('help')}</button></div></header><div class="page"><div class="page-grid ${page==='library'?'library-layout':''}"><main id="main" class="main-content" tabindex="-1"></main><aside class="right-column" id="right"></aside></div><footer class="footer"><span>${t('footer')}</span><button id="about">${t('about')} ↗</button><span>ҚАЗ / РУС</span></footer></div></div></div><nav class="mobile-nav" aria-label="${t('navigation')}">${navItem('assistant','assistant','chat')}${navItem('library','library','book')}${navItem('saved','saved','bookmark')}<button id="mobile-new" aria-label="${t('new')}">${icon('plus')}<span>${t('new')}</span></button></nav>`;
 document.querySelectorAll('[data-nav]').forEach(e=>e.onclick=()=>navigate(e.dataset.nav));
 document.querySelectorAll('[data-lang]').forEach(e=>e.onclick=()=>{lang=e.dataset.lang;writeStore('enu-lang',lang);render();});
 $('#active-model-name').textContent=modelSettings.model||t('chooseModel');$('#model-settings').onclick=openSettings;$('#settings').onclick=openSettings;$('#model-settings').disabled=busy;$('#settings').disabled=busy;
 $('#new').onclick=newQuestion;$('#mobile-new').onclick=newQuestion;$('#help').onclick=about;$('#about').onclick=about;
 const h=$('#history');if(!history.length)h.append(node('small','fine-print',t('noHistory')));
 history.slice(0,7).forEach(item=>h.append(button(item.question,()=>{current=item;conversationMode=item.conversationMode||'documents';navigate('assistant');})));
 renderRight();if(page==='assistant')renderAssistant();else if(page==='library')renderLibrary();else renderSaved();
}
function renderRight(){const ready=documents.filter(d=>d.status==='ready').length;const pages=documents.reduce((n,d)=>n+d.page_count,0);$('#right').innerHTML=`<section class="source-panel"><div class="panel-heading">${icon('book')}${t('knowledge')}</div><div class="panel-body"><div class="big-number">${documents.length}<small>${t('docs')}</small></div><div class="mini-stats"><div><b>${ready}</b>${t('ready')}</div><div><b>${pages}</b>${t('pages')}</div></div><div class="category-list">${translations[lang].topics.map((text,i)=>`<div>${icon(['plane','book','test'][i])}<span>${text}</span></div>`).join('')}</div></div><button class="panel-button" id="view-docs">${t('allDocs')} →</button></section><section class="note"><strong>${icon('shield')}${t('noteTitle')}</strong><p>${t('note')}</p></section><div class="project-stamp"><span class="stamp-square">ENU</span>${t('stamp')}</div>`;$('#view-docs').onclick=()=>navigate('library');}
function renderAssistant(){
 const main=$('#main');main.innerHTML=`<div class="eyebrow"><span class="dot"></span>${t('grounded')}</div>`;if(modelSettings.hosted)main.append(node('p','hosted-notice',t('hostedNotice')));
 if(!current){const hero=node('section','welcome');hero.innerHTML=`<div class="spark">${icon('sparkle')}</div><div class="eyebrow">${t('greeting')}</div><h1>${t('headline')}<br><em>${t('highlight')}</em></h1><p class="intro">${t('intro')}</p>`;main.append(hero);}else{
 const turns=[...(current.turns||[]),current];
 for(const current of turns){const isBusy=busy&&current===turns.at(-1);
 const conversation=node('section','conversation');conversation.append(node('div','question-bubble',current.question));
 const head=node('div','answer-head');head.innerHTML=`<img src="/favicon.svg" alt="">ENU Көмек <small></small>`;head.querySelector('small').textContent=isBusy?t('thinking'):(current.model||t('results'));conversation.append(head);
 if(isBusy){const loading=node('div','loading');loading.setAttribute('role','status');loading.innerHTML=`<span class="pulse"></span>${t('loading')}`;conversation.append(loading);}
 else if(current.error){conversation.append(node('div','error-state',current.error));conversation.append(button(t('retry'),()=>ask(current.question),'secondary-button'));}
 else if(current.response){const r=current.response;conversation.append(node('p','answer-body',responseMessage(r)));if(r.mode==='general-chat')conversation.append(node('p','model-notice',t('generalNotice')));
 if(r.cloud_documents_blocked)conversation.append(node('p','model-notice',t('cloudBlocked')));if(r.provider_error)conversation.append(node('p','model-notice',providerError(r.provider_error)));if(r.model_error)conversation.append(node('p','model-notice',t('fallback')));
 if(r.steps?.length){conversation.append(node('h2','steps-title',t('stepsTitle')));const list=node('ol','answer-steps');r.steps.forEach(step=>list.append(node('li','',step)));conversation.append(list);}
 const evidence=node('details','sources-details');evidence.open=!['local-rag','local-extractive-summary'].includes(r.mode);evidence.append(node('summary','',`${t('evidenceTitle')} (${r.sources.length})`));
 r.sources.forEach((s,i)=>{const block=node('article','evidence');const header=node('div','evidence-head');header.append(node('span','refnum',String(i+1)),node('strong','',s.title));block.append(header,node('p','',s.text));const cite=button(`${s.location==='section'?t('section'):t('page')} ${s.page} · ${t('openOriginal')}`,()=>showDocument(s.document_id,s.page,s.location),'citation');cite.insertAdjacentHTML('afterbegin',icon('external'));block.append(cite);evidence.append(block);});
 if(r.sources.length){conversation.append(evidence);conversation.append(node('p','fine-print',t('notTranslated')));const actions=node('div','answer-actions');const copy=button(t('copy'),()=>copyAnswer(current),'');copy.insertAdjacentHTML('afterbegin',icon('copy'));const save=button(t('save'),()=>saveAnswer(current),'');save.insertAdjacentHTML('afterbegin',icon('bookmark'));const feedback=button(t('feedback'),()=>{writeStore('enu-feedback-'+current.id,true);toast(t('thanks'));},'');feedback.insertAdjacentHTML('afterbegin',icon('check'));actions.append(copy,save,feedback);conversation.append(actions);}else if(r.status==='not_found'){conversation.append(button(t('library'),()=>navigate('library'),'secondary-button'));}}
 main.append(conversation);}}
 main.append(composer());main.append(node('p','under-composer',t('privacy')));
 if(!current){const title=node('div','section-title');title.innerHTML=`<h2>${t('start')}</h2><span>${t('suggest')}</span>`;main.append(title);const suggestions=node('div','suggestions');translations[lang].examples.forEach((text,i)=>{const b=button('',()=>ask(text),'suggestion');b.innerHTML=`<span class="suggestion-icon">${icon(['plane','shield','test'][i])}</span>`;b.append(node('p','',text));b.insertAdjacentHTML('beforeend',icon('arrow','arrow'));suggestions.append(b);});main.append(suggestions);
 const title2=node('div','section-title');title2.innerHTML=`<h2>${t('recentDocs')}</h2>`;const more=button(t('allDocs')+' ↗',()=>navigate('library'));more.className='fine-print';title2.append(more);main.append(title2);const list=node('div','source-list');documents.filter(d=>d.role==='student').slice(0,3).forEach(d=>list.append(sourceRow(d)));if(loadError){list.append(node('p','error-state',t('error')),button(t('retry'),init,'secondary-button'));}else if(!documents.length){list.append(node('p','fine-print',t('empty')));}main.append(list);}
}
function composer(){const form=node('form','composer');const modes=node('div','chat-modes');modes.setAttribute('role','group');modes.setAttribute('aria-label',t('modeLabel'));['documents','general'].forEach(mode=>{const b=button(t(mode==='documents'?'documentsMode':'generalMode'),()=>{conversationMode=mode;newQuestion();},mode===conversationMode?'active':'');b.disabled=busy;b.setAttribute('aria-pressed',String(mode===conversationMode));modes.append(b);});form.innerHTML=`<label class="sr-only" for="question">${t('placeholder')}</label><textarea id="question" maxlength="1500" placeholder="${t('placeholder')}" rows="2" ${busy?'disabled':''}></textarea><div class="composer-foot"><span class="input-hint">${icon('lock')}${t('inputHint')}</span><button class="send" type="submit" ${busy?'disabled':''} aria-label="${t('send')}">${icon('up')}</button></div>`;form.prepend(modes);const modelLine=button('',openSettings,'composer-model');modelLine.append(node('span','',(modelSettings.provider!=='local'?'✦ ':'◈ ')+providerTitle(modelSettings.provider)),node('strong','',modelSettings.model||t('chooseModel')));modelLine.disabled=busy;form.append(modelLine);form.onsubmit=e=>{e.preventDefault();ask($('#question').value);};form.querySelector('textarea').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();form.requestSubmit();}};return form;}
async function ask(question){if(busy)return;question=question.trim();if(question.trim().length<3){toast(t('emptyQuestion'));return;}const turns=current?[...(current.turns||[]),{...current,turns:undefined}].slice(-8):[];const context=turns.filter(x=>!['greeting','thanks','help'].includes(x.response?.status)).slice(-6).map(x=>x.question.slice(0,1000));page='assistant';busy=true;current={id:crypto.randomUUID(),question,language:lang,turns,conversationMode};render();$('#question')?.scrollIntoView({block:'center',behavior:'auto'});try{const response=await api('/api/ask',{question,language:lang,role:'student',history:context,conversation_mode:conversationMode});current.response=response;current.model=modelSettings.model;if(['local-rag','general-chat'].includes(response.mode))chatReady=true;history=[current,...history.filter(h=>h.question!==question)].slice(0,20);writeStore('enu-history',history);}catch(error){current.error=error.message;}finally{busy=false;render();$('#question')?.focus({preventScroll:true});}}
function sourceRow(d){const b=button('',()=>showDocument(d.id),'source-row');b.innerHTML=`<span class="file-icon ${d.format==='DOCX'?'docx':''}">${d.format}</span>`;const title=node('span');title.append(node('strong','',d.title),node('small','',`${d.page_count} ${d.format==='PDF'?t('page'):t('section')} · ${d.format}`));b.append(title);b.insertAdjacentHTML('beforeend',icon('arrow','arrow'));return b;}
const topics=[['all','all'],['мобильност','mobile'],['үдеріс','rules'],['тест','testing'],['диплом','diploma']];
function matchesTopic(d){const title=d.title.toLowerCase();if(filter==='all')return true;if(filter==='мобильност')return /мобильност|ұтқыр/.test(title);if(filter==='үдеріс')return /үдеріс|политика|честност/.test(title);if(filter==='диплом')return /диплом|квр|выпуск/.test(title);return title.includes(filter);}
function renderLibrary(){const main=$('#main');main.innerHTML=`<div class="library-head"><div class="eyebrow">ENU / ${t('sources')}</div><h1>${t('libraryTitle')}</h1><p>${t('libraryDesc')}</p></div><div class="toolbar"><label class="search-box">${icon('search')}<input id="doc-search" placeholder="${t('findDoc')}" aria-label="${t('findDoc')}"></label><button class="primary-button" id="add-doc">${icon('plus')}${t('add')}</button><button class="icon-button" id="refresh-index" aria-label="${t('refresh')}">${icon('refresh')}</button></div><div class="filters">${topics.map(([v,k])=>`<button data-filter="${v}" class="${filter===v?'active':''}">${t(k)}</button>`).join('')}</div><label class="role-switch"><input type="checkbox" id="staff" ${staff?'checked':''}>${t('staff')}</label><div class="docs-table"><div class="table-header"><span>${t('name')}</span><span>${t('volume')}</span><span>${t('status')}</span><span></span></div><div id="doc-rows"></div></div><p class="table-count" id="table-count"></p>`;
 $('#doc-search').value=searchTerm;$('#doc-search').oninput=e=>{searchTerm=e.target.value;renderRows();};$('#staff').onchange=e=>{staff=e.target.checked;renderRows();};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;renderLibrary();});$('#add-doc').onclick=uploadDialog;$('#refresh-index').onclick=async e=>{e.currentTarget.disabled=true;try{await api('/api/reindex',{});await loadDocuments();render();toast(t('reindexed'));}catch(error){toast(error.message);$('#refresh-index').disabled=false;}};renderRows();}
function renderRows(){const rows=$('#doc-rows');rows.replaceChildren();const selected=documents.filter(d=>(staff||d.role!=='staff')&&matchesTopic(d)&&d.title.toLowerCase().includes(searchTerm.toLowerCase()));selected.forEach(d=>{const b=button('',()=>showDocument(d.id),'doc-row');const title=node('span','doc-title');title.innerHTML=`<span class="file-icon ${d.format==='DOCX'?'docx':''}">${d.format}</span>`;const wrap=node('span');wrap.append(node('strong','',d.title),node('small','',d.filename));title.append(wrap);b.append(title,node('span','',`${d.page_count} ${d.format==='PDF'?t('page'):t('section')}`));const status=node('span');status.append(node('span','status-pill'+(d.status==='ready'?'':' warn'),t(d.status==='ready'?'readyShort':'ocr')));b.append(status);const arrow=node('span');arrow.innerHTML=icon('chevron');b.append(arrow);rows.append(b);});if(!selected.length)rows.append(node('div','empty-state',t('empty')));$('#table-count').textContent=`${selected.length} / ${documents.length} ${t('docs')}`;}
function renderSaved(){const main=$('#main');main.innerHTML=`<div class="saved-head"><div class="eyebrow">ENU / ${t('saved')}</div><h1>${t('savedTitle')}</h1><p>${t('savedDesc')}</p></div>`;if(!saved.length){main.append(node('div','empty-state',t('noSaved')));return;}saved.forEach(item=>{const card=node('div','saved-card');const open=button('',()=>{current=item;conversationMode=item.conversationMode||'documents';navigate('assistant');});open.append(node('strong','',item.question),node('small','',`${item.response?.sources?.length||0} ${t('sources')}`));card.append(open,button(t('remove'),()=>{saved=saved.filter(s=>s.id!==item.id);writeStore('enu-saved',saved);renderSaved();},'remove'));main.append(card);});}
function saveAnswer(item){if(!saved.some(s=>s.id===item.id)){saved.unshift(item);saved=saved.slice(0,50);writeStore('enu-saved',saved);}toast(t('savedDone'));}
async function copyAnswer(item){const text=item.question+'\n\n'+responseMessage(item.response)+'\n\n'+item.response.sources.map((s,i)=>`[${i+1}] ${s.text}\n${s.title}, ${s.location==='section'?t('section'):t('page')} ${s.page}`).join('\n\n');try{await navigator.clipboard.writeText(text);toast(t('copied'));}catch{toast(t('error'));}}
function modal(title,wide=false){lastFocus=document.activeElement;const backdrop=node('div','modal-backdrop');backdrop.addEventListener('click',e=>{if(e.target===backdrop)closeModal();});const box=node('section','modal'+(wide?' wide':''));box.setAttribute('role','dialog');box.setAttribute('aria-modal','true');box.setAttribute('aria-labelledby','modal-title');const header=node('header','modal-head');header.append(node('h2','',title));header.querySelector('h2').id='modal-title';const close=button('',closeModal,'icon-button');close.innerHTML=icon('close');close.setAttribute('aria-label',t('close'));header.append(close);box.append(header);const body=node('div','modal-body');box.append(body);backdrop.append(box);$('#overlay').replaceChildren(backdrop);document.body.style.overflow='hidden';close.focus();return {body,box};}
function closeModal(){ $('#overlay').replaceChildren();document.body.style.overflow='';lastFocus?.focus();}
function showDocument(id,pageNumber=1,location='page'){const d=documents.find(d=>d.id===id);if(!d){toast(t('empty'));return;}const {body,box}=modal(d.title,true);const meta=node('div','modal-meta');if(d.ocr)meta.append(node('span','',lang==='kk'?'OCR мәтіні: түпнұсқамен тексеріңіз':'Текст OCR: проверьте по оригиналу'));meta.append(node('span','',d.format),node('span','',`${d.page_count} ${d.format==='PDF'?t('page'):t('section')}`),node('span','',t('unverified')));body.append(meta);if(d.format==='PDF'){const pager=node('div','preview-pager');const previous=button('←',()=>showDocument(id,Math.max(1,pageNumber-1)),'secondary-button');previous.disabled=pageNumber<=1;previous.setAttribute('aria-label',lang==='kk'?'Алдыңғы бет':'Предыдущая страница');const next=button('→',()=>showDocument(id,Math.min(d.page_count,pageNumber+1)),'secondary-button');next.disabled=pageNumber>=d.page_count;next.setAttribute('aria-label',lang==='kk'?'Келесі бет':'Следующая страница');pager.append(previous,node('span','',`${t('page')} ${pageNumber} / ${d.page_count}`),next);body.append(pager);const preview=node('div','pdf-preview');const image=document.createElement('img');image.src=`/api/documents/${id}/preview/${pageNumber}`;image.alt=`${d.title} · ${t('page')} ${pageNumber}`;image.onerror=()=>preview.replaceChildren(node('p','',lang==='kk'?'Алдын ала қарау қолжетімсіз. Түпнұсқа файлын ашыңыз.':'Предпросмотр недоступен. Откройте оригинал файла.'));preview.append(image);box.append(preview);}else{body.append(node('p','',t('docxNote')));const text=current?.response?.sources?.find(s=>s.document_id===id&&s.page===pageNumber)?.text;if(text)body.append(node('p','',text));}const actions=node('div','modal-actions');const link=node('a','primary-button',t('download'));link.href=`/api/documents/${id}/file${d.format==='PDF'?'#page='+pageNumber:''}`;link.target='_blank';link.rel='noopener';const portal=node('a','secondary-button',t('sourceCatalog'));portal.href=d.source_url;portal.target='_blank';portal.rel='noopener noreferrer';actions.append(link,portal);body.append(actions);}
function openSettings(){
 if(busy)return;
 const {body}=modal(t('settings'),true);body.classList.add('settings-body');
 const intro=node('div','settings-intro');intro.append(node('span','connection-orb','✦'),node('p','',t('settingsIntro')));body.append(intro);
 const form=node('form','settings-form');const providerLabel=node('label','field-label',t('provider'));const provider=node('select','settings-select');provider.id='provider-choice';providerLabel.htmlFor=provider.id;
 [['gemini','Google Gemini'],['openai','ChatGPT · OpenAI API'],['anthropic','Claude · Anthropic API'],['local','Ollama · Qwen 2.5 3B']].filter(([value])=>!modelSettings.hosted||value!=='local').forEach(([value,label])=>{const option=node('option','',label);option.value=value;provider.append(option);});provider.value=modelSettings.provider;form.append(providerLabel,provider);
 const cloud=node('section','cloud-settings');const keyLabel=node('label','field-label');const key=node('input','settings-input');key.type='password';key.maxLength=2048;key.autocomplete='off';key.spellcheck=false;key.id='provider-api-key';keyLabel.htmlFor=key.id;
 const keyStatus=node('span','key-status');cloud.append(keyLabel,key,keyStatus,node('p','fine-print',t(modelSettings.hosted?'hostedKeySecurity':'keySecurity')));
 const status=node('p','settings-status');status.setAttribute('role','status');status.setAttribute('aria-live','polite');
 const refresh=button(t('connection'),async()=>{setLoading(true);status.textContent=t('modelLoading');const target=provider.value;try{await persist(false);const data=await api('/api/models',{provider:target});modelCache[target]=data.models;drawModels();status.textContent=`${t('connected')} · ${data.models.length}`;}catch(e){status.textContent=e.message;}finally{setLoading(false);}},'secondary-button');cloud.append(refresh);
 const searchLabel=node('label','field-label',t('searchModels'));const search=node('input','settings-input');search.id='model-search';search.type='search';search.placeholder=t('searchModels');searchLabel.htmlFor=search.id;cloud.append(searchLabel,search);
 const list=node('div','model-list');list.setAttribute('role','group');list.setAttribute('aria-label',t('chooseModel'));cloud.append(list);let selected='';
 function preference(id){return modelSettings.providers?.[id]||{key_saved:id===modelSettings.provider&&modelSettings.key_saved,model:id===modelSettings.provider?modelSettings.model:'',allow_documents:id===modelSettings.provider&&modelSettings.allow_documents};}
 function drawModels(){list.replaceChildren();const candidates=(modelCache[provider.value]||[]).filter(m=>(m.name+' '+m.id).toLowerCase().includes(search.value.toLowerCase()));if(!candidates.length){list.append(node('p','',t('modelSearchEmpty')));return;}candidates.forEach(m=>{const b=button('',()=>{selected=m.id;drawModels();},'model-option'+(selected===m.id?' selected':''));b.disabled=m.chat_supported===false;b.setAttribute('aria-pressed',String(selected===m.id));b.append(node('span','model-option-symbol','✦'));const label=node('span');label.append(node('strong','',m.name),node('small','',m.id+(m.chat_supported===false?' · '+t('notChat'):'')));b.append(label,node('span','model-check',selected===m.id?'✓':'↗'));list.append(b);});}
 search.oninput=drawModels;
 const consentLabel=node('label','cloud-consent');const consent=node('input');consent.type='checkbox';consentLabel.append(consent,node('span','',t('cloudConsent')));const privacy=node('p','settings-privacy');cloud.append(privacy,consentLabel);form.append(cloud);
 const local=node('p','local-settings',t('localNote'));form.append(local);
 function updateKeyState(){const saved=preference(provider.value).key_saved;keyStatus.textContent=t(saved?'keySaved':'keyEmpty');key.placeholder=t(saved?'keyPlaceholder':'apiKey');}
 function providerChanged(){const info=preference(provider.value);cloud.hidden=provider.value==='local';clear.hidden=provider.value==='local';local.hidden=provider.value!=='local';key.value='';search.value='';status.textContent='';selected=info.model||'';consent.checked=info.allow_documents===true;keyLabel.textContent=t('apiKey')+' · '+providerTitle(provider.value);privacy.textContent=cloudPrivacy(provider.value);updateKeyState();drawModels();}
 provider.onchange=providerChanged;
 async function persist(activate){const target=provider.value;if(activate&&target!=='local'&&!selected)throw Error(providerError('select_model'));if(activate&&target!=='local'&&!key.value.trim()&&!preference(target).key_saved)throw Error(providerError('key_required'));
 const data={key_provider:target,api_key:key.value.trim(),allow_documents:consent.checked};if(activate){data.provider=target;data.model=target==='local'?'qwen2.5:3b':selected;}modelSettings=await api('/api/settings',data);key.value='';updateKeyState();}
 function setLoading(value){refresh.disabled=value;save.disabled=value;clear.disabled=value;provider.disabled=value;key.disabled=value;}
 const actions=node('div','settings-actions');const save=button(t('saveSettings'),async()=>{setLoading(true);status.textContent='';try{await persist(true);closeModal();render();toast(t('savedSettings'));}catch(e){status.textContent=e.message;setLoading(false);}},'primary-button');
 const clear=button(t('clearKey'),async()=>{setLoading(true);try{const target=provider.value;const data={clear_key:true,key_provider:target};if(target===modelSettings.provider){data.provider=modelSettings.hosted?'gemini':'local';data.model=modelSettings.hosted?'':'qwen2.5:3b';}modelSettings=await api('/api/settings',data);delete modelCache[target];closeModal();render();toast(t('savedSettings'));}catch(e){status.textContent=e.message;setLoading(false);}},'text-danger');actions.append(clear,save);form.append(status,actions);form.onsubmit=e=>{e.preventDefault();save.click();};body.append(form);providerChanged();
 if(provider.value!=='local'&&preference(provider.value).key_saved&&!modelCache[provider.value]?.length){refresh.click();}
}

function about(){const {body}=modal(t('aboutTitle'));body.append(node('p','',t('aboutBody')),node('p','',t('aboutLimit')),node('p','fine-print',t('privacy')));const link=node('a','secondary-button',t('export'));link.href='/api/export';body.append(link);}
function uploadDialog(){const {body}=modal(t('uploadTitle'));body.append(node('p','',t(modelSettings.hosted?'hostedUpload':'uploadDesc')));const drop=node('div','dropzone');drop.innerHTML=icon('upload');const label=node('label','',t('choose'));const input=node('input');input.type='file';input.accept='.pdf,.docx';input.id='upload-file';label.htmlFor=input.id;drop.append(label,input);body.append(drop,node('p','fine-print',t(modelSettings.hosted?'hostedUpload':'uploadNote')));const status=node('p');status.setAttribute('role','status');body.append(status);const submit=button(t('add'),async()=>{const file=input.files[0];if(!file)return;if(file.size>(modelSettings.hosted?5000000:20000000)){status.textContent=t(modelSettings.hosted?'hostedUpload':'uploadDesc');return;}submit.disabled=true;input.disabled=true;status.textContent=t('uploading');try{const response=await fetch('/api/upload',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-Filename':encodeURIComponent(file.name)},body:file});const data=await response.json();if(!response.ok)throw Error(data.error);await loadDocuments();closeModal();navigate('library');toast(t('uploadDone'));}catch(error){status.textContent=error.message;submit.disabled=false;input.disabled=false;}},'primary-button');body.append(submit);}
document.addEventListener('keydown',event=>{const box=$('#overlay .modal');if(!box)return;if(event.key==='Escape'){closeModal();return;}if(event.key==='Tab'){const list=[...box.querySelectorAll('button,a[href],input,iframe')].filter(e=>!e.disabled);const first=list[0],last=list.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
async function loadDocuments(){documents=(await api('/api/documents')).documents;loadError=false;}
async function init(){render();try{await loadDocuments();const health=await api('/api/health');chatReady=health.chat_available===true;modelSettings=health.settings||modelSettings;if(modelSettings.hosted)conversationMode='general';}catch{loadError=true;}render();}
init();
